import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class FastDateFormat_format_TriageGen2Test {





    @Test
    public void testFormatWithLocale() {
        // Test with French locale to ensure locale-specific formatting (e.g., month names)
        FastDateFormat fdf = FastDateFormat.getInstance("MMMM", Locale.FRENCH);
        Calendar cal = Calendar.getInstance(Locale.FRENCH);
        cal.set(2023, Calendar.JANUARY, 1);
        Date date = cal.getTime();

        String result = fdf.format(date);
        // January in French is "janvier"
        assertEquals("janvier", result.toLowerCase());
    }








}

