import static org.junit.Assert.assertNotNull;

public class FastDateFormat_format_TriageGen2Test {











    @Test
    public void testFormatWithComplexPattern() {
        FastDateFormat fdf = FastDateFormat.getInstance("E, dd MMM yyyy HH:mm:ss Z");
        Date date = new Date(1672531200000L);
        String result = fdf.format(date);
        // Example: Sun, 01 Jan 2023 00:00:00 +0800
        // We check if it contains key segments to avoid brittle tests across environments
        assert(result.contains("2023"));
        assert(result.contains("Jan"));
    }


